const ok = items.filter(i => i.json.status === 'ok');
const combined = ok.map(i => '### SOURCE: ' + i.json.source_name + ' (' + i.json.url + ')\n' + i.json.raw_text).join('\n\n---\n\n');
return [{ json: {
  combined_text: combined || 'No sources returned usable content this run.',
  sources_ok_count: ok.length,
  sources_failed: items.filter(i => i.json.status !== 'ok').map(i => ({ source_name: i.json.source_name, url: i.json.url, status: i.json.status }))
}}];

const agg = $('Filter OK + Aggregate').first().json;
return [{ json: {
  trends: ($json.output && $json.output.trends) ? $json.output.trends : [],
  sources_ok_count: agg.sources_ok_count,
  sources_failed: agg.sources_failed,
  trend_provider: $json.ai_provider
}}];
